CREATE TABLE shift_doctors (
  shift_id bigint NOT NULL,
  doctor_id bigint NOT NULL,
  on_call boolean NOT NULL,
  PRIMARY KEY (shift_id, doctor_id)
);
INSERT INTO shift_doctors VALUES (42, 1, true), (42, 2, true);
-- Не рассчитывайте на CHECK по отдельной строке для COUNT(*) по смене.

BEGIN TRANSACTION ISOLATION LEVEL REPEATABLE READ;
SELECT doctor_id FROM shift_doctors
 WHERE shift_id = 42 AND on_call;
-- Остановитесь: дайте сессии B выполнить свой SELECT.
UPDATE shift_doctors SET on_call = false
 WHERE shift_id = 42 AND doctor_id = 1;
COMMIT;
-- В сессии B измените doctor_id = 2 и также COMMIT.

CREATE TABLE shift_guard (shift_id bigint PRIMARY KEY);
INSERT INTO shift_guard VALUES (42);
-- Каждый запрос на снятие врача делает следующее в одной транзакции:
BEGIN; -- PostgreSQL Read Committed по умолчанию
SELECT shift_id FROM shift_guard WHERE shift_id = 42 FOR UPDATE;
SELECT count(*) AS active_count FROM shift_doctors
 WHERE shift_id = 42 AND on_call;
-- Приложение: если active_count <= 1, ROLLBACK и отказ.
-- Иначе (лишь если именно этот врач ещё on_call):
UPDATE shift_doctors SET on_call = false
 WHERE shift_id = 42 AND doctor_id = 1 AND on_call
 RETURNING doctor_id;
-- Если RETURNING пуст: обработать как повтор/отказ, а не слепой успех.
COMMIT;
